import{_ as r,l as i,o as e,c as l,v as o,p as d,x as n,d as s,i as E,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"对比学习与 InfoNCE","description":"","frontmatter":{"title":"对比学习与 InfoNCE","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/contrastive-infonce.md","filePath":"llm/contrastive-infonce.md","lastUpdated":1789023840000}'),f={name:"llm/contrastive-infonce.md"};function m(p,a,_,h,A,C){const t=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="对比学习与-infonce" tabindex="-1">对比学习与 InfoNCE <a class="header-anchor" href="#对比学习与-infonce" aria-label="Permalink to &quot;对比学习与 InfoNCE&quot;">​</a></h1><div class="epigraph"><p>把正确配对的向量拉近、把批内其它配对推远，温度缩放的 softmax 就是 InfoNCE。嵌入空间的余弦意义从这里来，不是从语言模型的 MLM 头来。</p><footer>—— van den Oord 等 CPC 中的 InfoNCE；句向量实践见 [池化](/llm/embedding-pooling)</footer></div><p><a href="/llm/deployment-monitoring">上一课</a>收束对齐补层。本课程改做检索与嵌入：生成器之外需要可缓存的向量。主干已有池化与 <a href="/llm/clip">CLIP</a> 双塔；本课把损失钉成 InfoNCE，作为后课难负例、Matryoshka、指令嵌入的共同目标。缺口不是再讲 Transformer，而是：<strong>句向量要有度量目标</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/embedding-pooling">均值池化</a>给出 \\(z\\)，若仍只做 MLM，余弦没有语义。检索要把查询 \\(q\\) 与相关文档 \\(d^+\\) 拉近、与无关 \\(d^-\\) 推远。生成式交叉熵做不到「一批里谁更近」。需要一个在向量上的分类损失：把正对当成正确类，把批内其它文档当成负类。</p><p>van den Oord 等人把互信息下界写成 InfoNCE。CLIP、SimCLR、Sentence-BERT / 检索双塔用的都是同一族：温度缩放点积 + 交叉熵。后课默认「对比训练」指这一族，不再把三元组合页损失当默认。</p><p><span class="marginnote">本课的嵌入是检索向量，不是输入层 token embedding，也不是权重量化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>批内 \\(N\\) 个正对 \\((q_i,d_i)\\)，相似度 \\(s_{ij}=z_{q_i}^\\top z_{d_j}/\\tau\\)（向量已 \\(\\ell_2\\) 归一则是余弦）。对称 InfoNCE 常对行与列各做一次 softmax 交叉熵，与 CLIP 课同一形式。\\(\\tau\\) 过小会把损失变成几乎只看最难负例；过大则梯度平坦。双塔共享或不共享编码器，查询与文档可以非对称（短问对长文）。</p>',9)),(e(),d(c,null,{default:n(()=>[E(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%E5%A1%94%22%5D%20--%3E%20S%5B%22%E6%B8%A9%E5%BA%A6%E7%BC%A9%E6%94%BE%E7%82%B9%E7%A7%AF%22%5D%0A%20%20D%5B%22%E6%96%87%E6%A1%A3%E5%A1%94%22%5D%20--%3E%20S%0A%20%20S%20--%3E%20CE%5B%22%E6%89%B9%E5%86%85%E4%BA%A4%E5%8F%89%E7%86%B5%22%5D%0A%20%20CE%20--%3E%20Z%5B%22%E5%8F%AF%E4%BD%99%E5%BC%A6%E6%A3%80%E7%B4%A2%E7%9A%84%20z%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>InfoNCE 把「谁是正例」当成 \\(N\\) 类分类，负例越多，对互信息的下界越紧，经验上批要大。梯度来自正对不够近、以及与高分负例不够远。因此负例的难度决定空间有多细——下一课专门挖难负例。没有负例（只有正对回归）会塌缩：所有向量走向同一点，余弦无意义。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>批内负例假设「同一批里其它文档与 \\(q_i\\) 无关」。语义近邻碰巧同批会变成假负例，把同义文档推远。下一课用挖掘与去假负缓解。生成式 RAG 的阅读器仍是 LM；本课只训检索器。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>句向量的余弦来自 InfoNCE 一类对比损失，不是来自 MLM。</li><li>温度、批大小与是否对称决定梯度结构。</li><li>批内假负例是结构缺陷，交给难负例课。</li><li>出处：van den Oord 等 CPC / InfoNCE；CLIP；Reimers &amp; Gurevych Sentence-BERT。</li></ul>',6))])}const I=r(f,[["render",m]]);export{B as __pageData,I as default};
